import sys

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
logs = [(int(data[2 + 3 * i]), int(data[3 + 3 * i]), int(data[4 + 3 * i])) for i in range(m)]

def connected(T):
    adj = [[] for _ in range(n)]
    for t, a, b in logs:
        if t <= T:
            adj[a].append(b)
            adj[b].append(a)
    seen = {0}
    stack = [0]
    while stack:
        v = stack.pop()
        for w in adj[v]:
            if w not in seen:
                seen.add(w)
                stack.append(w)
    return len(seen) == n

ans = -1
for T in sorted(set(t for t, _, _ in logs)):
    if connected(T):
        ans = T
        break
print(ans)

