def gen(rng):
    def fmt(n, logs):
        return f'{n} {len(logs)}' + ''.join(f'\n{t} {a} {b}' for t, a, b in logs)

    def pair(n):
        a = rng.randrange(n)
        b = rng.randrange(n - 1)
        if b >= a:
            b += 1
        return a, b

    def rand_logs(n, m, tmax):
        return [(rng.randint(0, tmax), *pair(n)) for _ in range(m)]

    def spanning_late(n, extra, tmax):
        # a random spanning tree whose last edge arrives late, plus noise inside two halves
        perm = list(range(n))
        rng.shuffle(perm)
        logs = []
        for i in range(1, n):
            logs.append((rng.randint(0, tmax // 2), perm[i], perm[rng.randrange(i)]))
        logs.append((tmax, perm[0], perm[-1]))
        for _ in range(extra):
            logs.append((rng.randint(0, tmax), *pair(n)))
        rng.shuffle(logs)
        return logs

    tests = [
        fmt(2, [(0, 0, 1)]),
        fmt(2, [(10**9, 1, 0), (5, 0, 1)]),
        fmt(3, [(4, 0, 1), (4, 0, 1), (4, 1, 0)]),
        fmt(5, [(9, 0, 1), (9, 1, 2), (9, 2, 3), (9, 3, 4)]),
        fmt(5, [(1, 0, 1), (2, 1, 2), (3, 3, 4), (4, 0, 2), (5, 4, 3)]),
        fmt(4, [(8, 0, 1), (6, 1, 2), (4, 2, 3), (2, 3, 0)]),
    ]
    for n in (2, 3, 4, 5, 6, 8):
        tests.append(fmt(n, rand_logs(n, rng.randint(1, 3 * n), 20)))
    for n in (4, 7, 10):
        tests.append(fmt(n, spanning_late(n, rng.randint(0, n), 50)))
    for n in (6, 12):
        tests.append(fmt(n, rand_logs(n, 2 * n, 10**9)))
    def two_halves(n, m, tmax):
        # each half becomes connected internally; a few bridges arrive at random times
        perm = list(range(n))
        rng.shuffle(perm)
        h = n // 2
        logs = []
        for lo, hi in ((0, h), (h, n)):
            for i in range(lo + 1, hi):
                logs.append((rng.randint(0, tmax), perm[i], perm[rng.randrange(lo, i)]))
        for _ in range(5):
            logs.append((rng.randint(tmax // 2, tmax), perm[rng.randrange(h)], perm[rng.randrange(h, n)]))
        while len(logs) < m:
            lo, hi = (0, h) if rng.random() < 0.5 else (h, n)
            a, b = rng.sample(range(lo, hi), 2)
            logs.append((rng.randint(0, tmax), perm[a], perm[b]))
        rng.shuffle(logs)
        return logs

    tests.append(fmt(20000, spanning_late(20000, 20000, 10**9)))
    tests.append(fmt(20000, two_halves(20000, 40000, 10**9)))
    tests.append(fmt(20000, rand_logs(20000, 40000, 10**9)))
    return tests

